namespace gui_forms {

// AnchoredOverlayLayer's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/anchored_overlay_layer.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The overlay's preferred size, alignment, side, gap, margin and flip rule; resolved against the anchor on every arrangement (resolved_placement). An invalid placement throws std::invalid_argument.
template <typename Declaring>
struct AnchoredOverlayLayerPlacementCapability {
    PropertyCell<AnchoredOverlayPlacement, AnchoredOverlayLayerPlacementCapability<Declaring>> placement{};

    static void assign(AnchoredOverlayLayerPlacementCapability& capability, AnchoredOverlayPlacement incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.placement), incoming);
        if (!capability.placement.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.placement));
    }
};

// Whether a press outside the content raises dismiss_requested(click_away). The layer only reports it; the owner closes the overlay.
template <typename Declaring>
struct AnchoredOverlayLayerDismissOnClickAwayCapability {
    PropertyCell<bool, AnchoredOverlayLayerDismissOnClickAwayCapability<Declaring>> dismiss_on_click_away{true};

    static void assign(AnchoredOverlayLayerDismissOnClickAwayCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.dismiss_on_click_away), incoming);
        if (!capability.dismiss_on_click_away.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.dismiss_on_click_away));
    }
};

// Whether Escape raises dismiss_requested(escape_key). The layer only reports it; the owner closes the overlay.
template <typename Declaring>
struct AnchoredOverlayLayerDismissOnEscapeCapability {
    PropertyCell<bool, AnchoredOverlayLayerDismissOnEscapeCapability<Declaring>> dismiss_on_escape{true};

    static void assign(AnchoredOverlayLayerDismissOnEscapeCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.dismiss_on_escape), incoming);
        if (!capability.dismiss_on_escape.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.dismiss_on_escape));
    }
};

// Every AnchoredOverlayLayer capability, in the order the declaring class takes them.
template <typename Declaring>
struct AnchoredOverlayLayerCapabilities : public AnchoredOverlayLayerPlacementCapability<Declaring>,
                                          public AnchoredOverlayLayerDismissOnClickAwayCapability<Declaring>,
                                          public AnchoredOverlayLayerDismissOnEscapeCapability<Declaring> {};

} // namespace gui_forms
